GS_ADD([{"id":"fr-jorf-casino-qvct-extension","reg":"Europe","mk":"FR","mkt":"France","auth":"Ministry of Labour","cat":"Other","date":"2026-11-19","v":"official","t":"France: casino staff agreement on working conditions becomes binding across the sector","d":"An order published in the Journal officiel on 19 November extends amendment no. 39 of the national casinos collective agreement, on quality of working life, to all employers and staff in its scope.","b":["An order (arrêté) of 9 November 2026, published in the Journal officiel no. 0270 of 19 November 2026, extends amendment no. 39 of 7 January 2026 to the national collective agreement for casinos of 29 March 2002 (no. 2257).","The amendment covers quality of working life and working conditions. Article 1 of the order makes it binding on all employers and employees within the scope of the agreement. Article 2 says the extension applies from the date of publication, for the rest of the amendment's term."],"src":[["Légifrance, Arrêté du 9 novembre 2026 portant extension d'un avenant à la convention collective nationale des casinos (n° 2257), JORF no. 0270 of 19 November 2026","https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000055103077","o"]],"es":{"mkt":"Francia","auth":"Ministerio de Trabajo","t":"Francia: el acuerdo del personal de casinos sobre condiciones de trabajo pasa a ser obligatorio en todo el sector","d":"Una orden publicada en el Journal officiel el 19 de noviembre extiende la enmienda n.º 39 del convenio colectivo nacional de casinos, sobre calidad de vida laboral, a todos los empleadores y trabajadores de su ámbito.","b":["Una orden (arrêté) de 9 de noviembre de 2026, publicada en el Journal officiel n.º 0270 de 19 de noviembre de 2026, extiende la enmienda n.º 39, de 7 de enero de 2026, al convenio colectivo nacional de casinos de 29 de marzo de 2002 (n.º 2257).","La enmienda trata de la calidad de vida laboral y las condiciones de trabajo. El artículo 1 de la orden la hace obligatoria para todos los empleadores y trabajadores del ámbito del convenio. El artículo 2 dice que la extensión se aplica desde la fecha de publicación, durante el resto de la vigencia de la enmienda."]},"ru":{"mkt":"Франция","auth":"Министерство труда","t":"Франция: соглашение персонала казино об условиях труда стало обязательным для всей отрасли","d":"Приказ, опубликованный в Journal officiel 19 ноября, распространяет поправку № 39 к национальному коллективному договору казино о качестве трудовой жизни на всех работодателей и работников в сфере его действия.","b":["Приказ (arrêté) от 9 ноября 2026 года, опубликованный в Journal officiel № 0270 от 19 ноября 2026 года, распространяет поправку № 39 от 7 января 2026 года к национальному коллективному договору казино от 29 марта 2002 года (№ 2257).","Поправка касается качества трудовой жизни и условий труда. Статья 1 приказа делает ее обязательной для всех работодателей и работников в сфере действия договора. Согласно статье 2, распространение действует с даты публикации до окончания срока действия поправки."]}},{"id":"tw-cib-taichung-15bn-ring","reg":"Asia","mk":"TW","mkt":"Taiwan","auth":"Criminal Investigation Bureau","cat":"Enforcement","date":"2026-11-19","v":"official","t":"Taiwan: police break a Taichung gambling ring that handled more than NT$15.5 billion in bets in nearly a year, 34 referred","d":"The ring ran a customer-service server room and an underground Texas hold'em casino, and used cash to avoid money trails, police say.","b":["The Criminal Investigation Bureau has broken up a gambling ring in Taichung that handled more than NT$15.5 billion in bets over nearly a year, the state news agency CNA reported on 19 November. The bureau's Sixth Investigation Brigade worked with the Taichung City Police Department, under the direction of the Taichung District Prosecutors Office.","The investigation began in July. A joint task force searched 22 locations in August and October and caught 22 suspects, including online casino operators, a physical casino operator and agents, as well as 12 gamblers. All 34 were referred to the Taichung District Prosecutors Office.","Police say the ring ran a customer-service server room in a commercial building in Beitun District and an underground Texas hold'em casino with gambling machines. It offered online live baccarat, slots, sports betting and lottery betting, and used cash to avoid leaving money trails. Officers seized more than NT$1.2 million in cash, gambling machines, phones and computers.","The suspects face gambling charges under the Criminal Code and charges under the Money Laundering Control Act."],"src":[["CNA, CIB breaks up large Taichung gambling ring, 19 Nov 2026","https://www.cna.com.tw/news/asoc/202611190092.aspx","o"]],"es":{"mkt":"Taiwán","auth":"Oficina de Investigación Criminal","t":"Taiwán: la policía desarticula en Taichung una red de juego que movió más de 15.500 millones de dólares taiwaneses en apuestas en casi un año, con 34 remitidos a la fiscalía","d":"La red tenía una sala de servidores de atención al cliente y un casino clandestino de Texas hold'em, y usaba efectivo para no dejar rastro del dinero, según la policía.","b":["La Oficina de Investigación Criminal ha desarticulado en Taichung una red de juego que movió más de 15.500 millones de dólares taiwaneses en apuestas en casi un año, informó la agencia estatal de noticias CNA el 19 de noviembre. La Sexta Brigada de Investigación de la oficina trabajó con el Departamento de Policía de la ciudad de Taichung, bajo la dirección de la Fiscalía del Distrito de Taichung.","La investigación empezó en julio. Un equipo conjunto registró 22 lugares en agosto y octubre y detuvo a 22 sospechosos, entre ellos operadores de casinos online, un operador de casino físico y agentes, además de 12 jugadores. Los 34 fueron remitidos a la Fiscalía del Distrito de Taichung.","La policía dice que la red tenía una sala de servidores de atención al cliente en un edificio comercial del distrito de Beitun y un casino clandestino de Texas hold'em con máquinas de juego. Ofrecía bacará en vivo online, tragaperras, apuestas deportivas y apuestas de lotería, y usaba efectivo para no dejar rastro del dinero. Los agentes incautaron más de 1,2 millones de dólares taiwaneses en efectivo, máquinas de juego, teléfonos y ordenadores.","Los sospechosos se enfrentan a cargos de juego según el Código Penal y a cargos según la Ley de Control del Blanqueo de Capitales."]},"ru":{"mkt":"Тайвань","auth":"Бюро уголовных расследований","t":"Тайвань: полиция ликвидировала в Тайчжуне игорную группу с оборотом ставок более 15,5 млрд тайваньских долларов почти за год, 34 человека переданы прокуратуре","d":"По данным полиции, группа содержала серверную службы поддержки клиентов и подпольное казино техасского холдема и использовала наличные, чтобы не оставлять следов денег.","b":["Бюро уголовных расследований ликвидировало в Тайчжуне игорную группу, принявшую ставок более чем на 15,5 млрд тайваньских долларов почти за год, сообщило 19 ноября государственное агентство CNA. Шестая следственная бригада бюро действовала вместе с полицейским управлением города Тайчжун под руководством окружной прокуратуры Тайчжуна.","Расследование началось в июле. В августе и октябре совместная группа провела обыски в 22 местах и задержала 22 подозреваемых, в том числе операторов онлайн-казино, оператора наземного казино и агентов, а также 12 игроков. Все 34 человека переданы окружной прокуратуре Тайчжуна.","По данным полиции, группа содержала серверную службы поддержки клиентов в коммерческом здании в районе Бэйтунь и подпольное казино техасского холдема с игровыми автоматами. Она предлагала онлайн-баккара с живыми дилерами, слоты, спортивные ставки и ставки на лотереи и использовала наличные, чтобы не оставлять следов денег. Изъяты более 1,2 млн тайваньских долларов наличными, игровые автоматы, телефоны и компьютеры.","Подозреваемым грозят обвинения в организации азартных игр по Уголовному кодексу и обвинения по Закону о контроле за отмыванием денег."]}},{"id":"mt-mga-vittoriosa-b2b-cancelled","reg":"Europe","mk":"MT","mkt":"Malta","auth":"MGA","cat":"Enforcement","date":"2026-11-18","v":"official","t":"Malta: MGA cancels the B2B authorisation of Vittoriosa Consultancy Limited","d":"The Malta Gaming Authority has cancelled the B2B authorisation held by Vittoriosa Consultancy Limited, with effect from 13 November 2026.","b":["The Malta Gaming Authority said on 18 November 2026 that it has cancelled B2B authorisation MGA/B2B/989/2022, held by Vittoriosa Consultancy Limited (C 73106). The cancellation took effect on 13 November.","The authority acted under regulations 9(1)(c), (d), (l) and (m) and 10(1)(a) of the Gaming Compliance and Enforcement Regulations (S.L. 583.06). Its notice gives no further reasons.","The company must settle any outstanding fees and remove all references to the authority and to the authorisation, as article 51 of the Gaming Act requires. It can appeal under article 43 of the Act."],"src":[["MGA notice, 18 Nov 2026","https://www.mga.org.mt/cancellation-of-authorisation-for-vittoriosa-consultancy-limited-c-73106/","o"]],"es":{"mkt":"Malta","auth":"MGA","t":"Malta: la MGA cancela la autorización B2B de Vittoriosa Consultancy Limited","d":"La Malta Gaming Authority ha cancelado la autorización B2B de Vittoriosa Consultancy Limited, con efecto desde el 13 de noviembre de 2026.","b":["La Malta Gaming Authority dijo el 18 de noviembre de 2026 que ha cancelado la autorización B2B MGA/B2B/989/2022, de la que era titular Vittoriosa Consultancy Limited (C 73106). La cancelación tuvo efecto el 13 de noviembre.","La autoridad actuó en virtud de los reglamentos 9(1)(c), (d), (l) y (m) y 10(1)(a) del Reglamento de Cumplimiento y Control del Juego (S.L. 583.06). Su aviso no da más motivos.","La empresa debe pagar las tasas pendientes y retirar toda referencia a la autoridad y a la autorización, como exige el artículo 51 de la Ley del Juego. Puede recurrir según el artículo 43 de la ley."]},"ru":{"mkt":"Мальта","auth":"MGA","t":"Мальта: MGA аннулировал B2B-разрешение Vittoriosa Consultancy Limited","d":"Malta Gaming Authority аннулировал B2B-разрешение компании Vittoriosa Consultancy Limited с 13 ноября 2026 года.","b":["Malta Gaming Authority 18 ноября 2026 года сообщил об аннулировании B2B-разрешения MGA/B2B/989/2022, выданного Vittoriosa Consultancy Limited (C 73106). Аннулирование вступило в силу 13 ноября.","Регулятор действовал на основании правил 9(1)(c), (d), (l) и (m) и 10(1)(a) Положения о соблюдении требований и надзоре в сфере азартных игр (S.L. 583.06). Других причин в уведомлении не указано.","Компания должна погасить задолженность по сборам и удалить все упоминания регулятора и разрешения, как того требует статья 51 Закона об азартных играх. Она может обжаловать решение по статье 43 закона."]}},{"id":"pl-mf-register-nov-16-18-134","reg":"Europe","mk":"PL","mkt":"Poland","auth":"Ministry of Finance","cat":"Enforcement","date":"2026-11-18","v":"official","t":"Poland: finance ministry adds 134 domains to its register of banned gambling sites on 16 to 18 November","d":"Poland's finance ministry added 1 domain on 16 November, 32 on 17 November and 101 on 18 November to its register of illegal gambling sites.","b":["Poland's Ministry of Finance added 134 domains to its register of domains used to offer gambling against the law in updates on 16, 17 and 18 November 2026.","The register data shows 1 entry dated 16 November, 32 dated 17 November and 101 dated 18 November. The latest entry was added at 13:26 on 18 November. Background: the ministry added 97 domains on 12 and 13 November."],"src":[["Ministry of Finance, Register of domains used to offer gambling contrary to the Act","https://hazard.mf.gov.pl/","o"],["Ministry of Finance, register data","https://hazard.mf.gov.pl/api/Register","o"]],"es":{"mkt":"Polonia","auth":"Ministerio de Finanzas","t":"Polonia: el Ministerio de Finanzas añade 134 dominios a su registro de webs de juego prohibidas entre el 16 y el 18 de noviembre","d":"El Ministerio de Finanzas de Polonia añadió 1 dominio el 16 de noviembre, 32 el 17 de noviembre y 101 el 18 de noviembre a su registro de webs de juego ilegal.","b":["El Ministerio de Finanzas de Polonia añadió 134 dominios a su registro de dominios usados para ofrecer juego en contra de la ley en las actualizaciones del 16, 17 y 18 de noviembre de 2026.","Los datos del registro muestran 1 entrada con fecha de 16 de noviembre, 32 con fecha de 17 de noviembre y 101 con fecha de 18 de noviembre. La última entrada se añadió a las 13:26 del 18 de noviembre. Antecedentes: el ministerio añadió 97 dominios el 12 y el 13 de noviembre."]},"ru":{"mkt":"Польша","auth":"Министерство финансов","t":"Польша: министерство финансов добавило 134 домена в реестр запрещенных игорных сайтов 16, 17 и 18 ноября","d":"Министерство финансов Польши добавило в реестр нелегальных игорных сайтов 1 домен 16 ноября, 32 домена 17 ноября и 101 домен 18 ноября.","b":["Министерство финансов Польши в обновлениях 16, 17 и 18 ноября 2026 года добавило 134 домена в реестр доменов, используемых для незаконной организации азартных игр.","По данным реестра, 1 запись датирована 16 ноября, 32 записи 17 ноября и 101 запись 18 ноября. Последняя запись добавлена в 13:26 18 ноября. Справочно: 12 и 13 ноября министерство добавило 97 доменов."]}},{"id":"ro-cernavoda-gambling-rules-100m","reg":"Europe","mk":"RO","mkt":"Romania","auth":"Cernavoda Local Council","cat":"Licensing","date":"2026-11-18","v":"official","t":"Romania: Cernavoda council adopts gambling rules with a 100 metre buffer and a fee of 100 lei per square metre","d":"Cernavoda city council approved a gambling regulation that bars venues within 100 metres of schools, cultural, health and religious institutions and sets a yearly hall fee.","b":["Cernavoda city council approved a regulation on gambling on the evening of 18 November 2026, the public broadcaster Radio Romania Constanta reported. The draft came from the mayor.","Gambling is allowed across the city except inside, or within 100 metres of, educational, arts, cultural, health or religious institutions. The fee for gambling halls is 100 lei per square metre per year.","A request for a secret ballot could not be met because the session was held partly in person and partly remotely. The vote count and full text have not been published."],"src":[["Radio Romania Constanta, Cernavoda council on gambling rules, 18 Nov 2026","https://www.radioconstanta.ro/2026/11/18/cernavoda-jocurile-de-tip-pacanele-permise/","o"],["Jurnal de Constanta","https://www.jurnaldeconstanta.ro/consiliul-local-cernavoda-in-actiune-decizii-importante-privind-regulamentele-jocurilor-de-noroc-si-alte-initiative/","p"]],"es":{"mkt":"Rumanía","auth":"Consejo Local de Cernavoda","t":"Rumanía: el consejo de Cernavoda aprueba normas de juego con una distancia de 100 metros y una tasa de 100 lei por metro cuadrado","d":"El consejo municipal de Cernavoda aprobó un reglamento del juego que prohíbe los locales a menos de 100 metros de centros educativos, culturales, sanitarios y religiosos y fija una tasa anual para los salones.","b":["El consejo municipal de Cernavoda aprobó un reglamento sobre el juego la tarde del 18 de noviembre de 2026, informó la emisora pública Radio Romania Constanta. El proyecto lo presentó el alcalde.","El juego está permitido en toda la ciudad salvo dentro de centros educativos, artísticos, culturales, sanitarios o religiosos, o a menos de 100 metros de ellos. La tasa para los salones de juego es de 100 lei por metro cuadrado al año.","No se pudo atender una petición de voto secreto porque la sesión fue en parte presencial y en parte a distancia. No se han publicado el resultado de la votación ni el texto completo."]},"ru":{"mkt":"Румыния","auth":"Местный совет Чернаводэ","t":"Румыния: совет Чернаводэ принял правила азартных игр с зоной 100 метров и сбором 100 леев за квадратный метр","d":"Городской совет Чернаводэ утвердил регламент азартных игр, который запрещает игорные заведения ближе 100 метров от учебных, культурных, медицинских и религиозных учреждений и устанавливает ежегодный сбор для залов.","b":["Городской совет Чернаводэ вечером 18 ноября 2026 года утвердил регламент об азартных играх, сообщила общественная радиостанция Radio Romania Constanta. Проект внес мэр.","Азартные игры разрешены по всему городу, кроме территории учебных, художественных, культурных, медицинских или религиозных учреждений и зоны 100 метров вокруг них. Сбор для игорных залов составляет 100 леев за квадратный метр в год.","Просьбу о тайном голосовании выполнить не удалось, так как заседание проходило частично очно, частично дистанционно. Итоги голосования и полный текст не опубликованы."]}},{"id":"gb-dcms-hl4794-sponsorship","reg":"Europe","mk":"GB","mkt":"United Kingdom","auth":"DCMS","cat":"Advertising","date":"2026-11-17","v":"official","t":"UK: government says it will set out next steps on unlicensed gambling sponsorship","d":"In a Lords written answer on 17 November, the culture department welcomed the Premier League's front-of-shirt gambling sponsorship ban and said next steps on unlicensed sponsorship will follow.","b":["The Department for Culture, Media and Sport answered two Lords written questions on gambling advertising on 17 November 2026. Both were tabled on 2 November 2026.","In answer HL4794, on gambling advertising in football coverage, the department said the link between sport and gambling must be handled carefully because of its impact on children and young people. It welcomed the start of the Premier League's ban on front-of-shirt gambling sponsorship. It said the government will set out next steps on unlicensed sponsorship and keeps working with stakeholders on further action. The answer gives no date.","In answer HL4793, on social media advertising, the department restated that Advertising Standards Authority codes require operators to use all available social media tools to keep adverts away from under-18s and other vulnerable groups where possible. Adverts must not feature anyone who is, or appears to be, under 25. The department said it reviews advertising rules regularly."],"src":[["UK Parliament, written question HL4794, answered 17 November 2026","https://questions-statements-api.parliament.uk/api/writtenquestions/questions/1955738","o"],["UK Parliament, written question HL4793, answered 17 November 2026","https://questions-statements-api.parliament.uk/api/writtenquestions/questions/1955739","o"]],"es":{"mkt":"Reino Unido","auth":"DCMS","t":"Reino Unido: el Gobierno dice que anunciará los próximos pasos sobre el patrocinio de juego sin licencia","d":"En una respuesta escrita a los Lores el 17 de noviembre, el departamento de Cultura celebró la prohibición de la Premier League del patrocinio de juego en la parte frontal de las camisetas y dijo que habrá próximos pasos sobre el patrocinio sin licencia.","b":["El Departamento de Cultura, Medios y Deporte respondió el 17 de noviembre de 2026 a dos preguntas escritas de los Lores sobre la publicidad del juego. Ambas se registraron el 2 de noviembre de 2026.","En la respuesta HL4794, sobre la publicidad del juego en las retransmisiones de fútbol, el departamento dijo que el vínculo entre el deporte y el juego debe gestionarse con cuidado por su impacto en niños y jóvenes. Celebró el inicio de la prohibición de la Premier League del patrocinio de juego en la parte frontal de las camisetas. Dijo que el Gobierno anunciará los próximos pasos sobre el patrocinio sin licencia y que sigue trabajando con las partes interesadas en nuevas medidas. La respuesta no da fecha.","En la respuesta HL4793, sobre la publicidad en redes sociales, el departamento recordó que los códigos de la Advertising Standards Authority obligan a los operadores a usar todas las herramientas de las redes sociales para alejar los anuncios de los menores de 18 años y de otros grupos vulnerables cuando sea posible. Los anuncios no pueden mostrar a nadie que tenga, o parezca tener, menos de 25 años. El departamento dijo que revisa las normas de publicidad con regularidad."]},"ru":{"mkt":"Великобритания","auth":"DCMS","t":"Великобритания: правительство заявило, что представит следующие шаги по спонсорству нелицензированных игорных компаний","d":"В письменном ответе Палате лордов 17 ноября министерство культуры приветствовало запрет Премьер-лиги на игорную рекламу на лицевой стороне футболок и заявило, что последуют шаги по нелицензированному спонсорству.","b":["Министерство культуры, СМИ и спорта 17 ноября 2026 года ответило на два письменных вопроса Палаты лордов о рекламе азартных игр. Оба вопроса были поданы 2 ноября 2026 года.","В ответе HL4794 о рекламе азартных игр в футбольных трансляциях министерство заявило, что к связи спорта и азартных игр нужно подходить осторожно из-за ее влияния на детей и молодежь. Оно приветствовало вступление в силу запрета Премьер-лиги на игорное спонсорство на лицевой стороне футболок. Министерство сообщило, что правительство представит следующие шаги по нелицензированному спонсорству и продолжает работу с заинтересованными сторонами над дальнейшими мерами. Сроки в ответе не указаны.","В ответе HL4793 о рекламе в социальных сетях министерство напомнило, что кодексы Advertising Standards Authority обязывают операторов использовать все доступные инструменты соцсетей, чтобы по возможности не показывать рекламу лицам до 18 лет и другим уязвимым группам. В рекламе не могут участвовать люди младше 25 лет или выглядящие младше 25 лет. Министерство сообщило, что регулярно пересматривает правила рекламы."]}},{"id":"dk-fatf-high-risk-lists","reg":"Europe","mk":"DK","mkt":"Denmark","auth":"Spillemyndigheden","cat":"Payments & AML","date":"2026-11-17","v":"official","t":"Denmark: gambling regulator tells operators to use updated FATF high-risk lists in player risk checks","d":"Spillemyndigheden told licence holders that the FATF has updated its lists of high-risk jurisdictions and that they must use them when assessing player risk.","b":["Spillemyndigheden said on 17 November 2026 that the FATF has updated its lists of high-risk jurisdictions. The grey list now has 18 jurisdictions. The black list has 3: North Korea, Iran and Myanmar.","Operators must take the FATF lists into account when they assess the risk of each player, based on Annex 3 of the Anti-Money Laundering Act on high-risk factors. Where a player is assessed as posing a higher risk, enhanced due diligence applies under section 17(1).","A FATF listing alone does not automatically require enhanced due diligence. Enhanced due diligence is mandatory under section 17(2) for players from countries on the EU list of high-risk third countries."],"src":[["Spillemyndigheden, FATF har opdateret lister over højrisikolande, 17 Nov 2026","https://spillemyndigheden.dk/nyheder/fatf-har-opdateret-lister-over-hoejrisikolande-1","o"]],"es":{"mkt":"Dinamarca","auth":"Spillemyndigheden","t":"Dinamarca: el regulador del juego pide a los operadores usar las listas de alto riesgo actualizadas del GAFI al evaluar a los jugadores","d":"Spillemyndigheden comunicó a los titulares de licencias que el GAFI ha actualizado sus listas de jurisdicciones de alto riesgo y que deben usarlas al evaluar el riesgo de los jugadores.","b":["Spillemyndigheden dijo el 17 de noviembre de 2026 que el GAFI ha actualizado sus listas de jurisdicciones de alto riesgo. La lista gris tiene ahora 18 jurisdicciones. La lista negra tiene 3: Corea del Norte, Irán y Myanmar.","Los operadores deben tener en cuenta las listas del GAFI al evaluar el riesgo de cada jugador, según el anexo 3 de la Ley de Prevención del Blanqueo de Capitales sobre factores de alto riesgo. Cuando se considera que un jugador presenta un riesgo mayor, se aplica la diligencia debida reforzada según el artículo 17(1).","La inclusión en una lista del GAFI no exige por sí sola la diligencia debida reforzada. Esta es obligatoria según el artículo 17(2) para los jugadores de países de la lista de la UE de terceros países de alto riesgo."]},"ru":{"mkt":"Дания","auth":"Spillemyndigheden","t":"Дания: игорный регулятор обязал операторов учитывать обновленные списки FATF при оценке рисков игроков","d":"Spillemyndigheden сообщил владельцам лицензий, что FATF обновила списки юрисдикций высокого риска и что их нужно использовать при оценке риска игроков.","b":["Spillemyndigheden 17 ноября 2026 года сообщил, что FATF обновила списки юрисдикций высокого риска. В сером списке теперь 18 юрисдикций. В черном списке 3: КНДР, Иран и Мьянма.","Операторы должны учитывать списки FATF при оценке риска каждого игрока на основании приложения 3 к Закону о ПОД/ФТ о факторах высокого риска. Если игрок признан игроком повышенного риска, применяется расширенная проверка по пункту 1 статьи 17.","Само по себе включение в список FATF не требует автоматически расширенной проверки. Расширенная проверка обязательна по пункту 2 статьи 17 для игроков из стран, включенных в список ЕС третьих стран высокого риска."]}},{"id":"do-dgja-res-03-04","reg":"Caribbean","mk":"DO","mkt":"Dominican Republic","auth":"DGJA","cat":"Licensing","date":"2026-11-17","v":"official","brief":true,"t":"Dominican regulator issues resolutions on Lotería Nacional sales points and outlet changes","d":"The DGJA has published Resolución 04-2026 on requirements to sell Lotería Nacional draws and Resolución 03-2026 on a simplified procedure for outlet ownership, name, address changes and closures.","b":["The Dominican gambling regulator DGJA has published two new resolutions in November 2026.","Resolución Núm. 04-2026, dated 17 November 2026, sets the mandatory requirements for selling Lotería Nacional draws through lottery outlets (bancas de lotería), agencies and points of sale, according to its title.","Resolución Núm. 03-2026, dated 10 November 2026, sets on a transitional basis the requirements and a simplified administrative procedure for a change of owner, a change of trade name, a move or change of address, and permanent closure. It applies to lottery outlets, sports betting outlets and bingos.","The DGJA has posted both resolutions as scanned files. Its news pages give only their titles and dates.","Background: the DGJA issued Resolutions 01-2026 and 02-2026 on 13 October 2026."],"src":[["DGJA, Resolución Núm. 04-2026, 17 Nov 2026","https://dgja.gob.do/noticias/resolucion-num-04-2026-que-establece-los-requisitos-obligatorios-para-comercializar-los-sorteos-de-la-loteria-nacional-a-traves-de-bancas-de-loteria-agencias-y-puntos-de-venta/","o"],["DGJA, Resolución Núm. 04-2026 (PDF)","https://dgja.gob.do/wp-content/uploads/2026/11/RESOLUCION-04-DEL-2026.-SCAN.pdf","o"],["DGJA, Resolución Núm. 03-2026, 10 Nov 2026","https://dgja.gob.do/noticias/resolucion-num-03-2026-que-establece-con-caracter-transitorio-los-requisitos-y-el-procedimiento-administrativo-simplificado-para-el-cambio-de-propietario-de-nombre-comercial-traslado-o-cambio-de/","o"],["DGJA, Resolución Núm. 03-2026 (PDF)","https://dgja.gob.do/wp-content/uploads/2026/11/Resolucion-Num.-03-2026.pdf","o"],["Listín Diario, 18 Nov 2026","https://listindiario.com/economia/bolsillo/20261118/bancas-registradas-dia-impuestos-podran-vender-sorteos-loteria-nacional_930636.html","p"]],"es":{"mkt":"República Dominicana","auth":"DGJA","t":"El regulador dominicano dicta resoluciones sobre puntos de venta de la Lotería Nacional y cambios en las bancas","d":"La DGJA ha publicado la Resolución 04-2026 sobre los requisitos para vender sorteos de la Lotería Nacional y la Resolución 03-2026 sobre un procedimiento simplificado para cambios de titular, nombre, domicilio y cierres de bancas.","b":["El regulador dominicano del juego, la DGJA, ha publicado dos nuevas resoluciones en noviembre de 2026.","La Resolución Núm. 04-2026, de 17 de noviembre de 2026, establece los requisitos obligatorios para comercializar los sorteos de la Lotería Nacional a través de bancas de lotería, agencias y puntos de venta, según su título.","La Resolución Núm. 03-2026, de 10 de noviembre de 2026, establece con carácter transitorio los requisitos y un procedimiento administrativo simplificado para el cambio de propietario, el cambio de nombre comercial, el traslado o cambio de domicilio y el cierre definitivo. Se aplica a bancas de lotería, bancas de apuestas deportivas y bingos.","La DGJA ha publicado ambas resoluciones como archivos escaneados. Sus páginas de noticias solo dan los títulos y las fechas.","Antecedentes: la DGJA dictó las Resoluciones 01-2026 y 02-2026 el 13 de octubre de 2026."]},"ru":{"mkt":"Доминиканская Республика","auth":"DGJA","t":"Доминиканский регулятор издал резолюции о точках продаж Lotería Nacional и изменениях в лотерейных пунктах","d":"DGJA опубликовала резолюцию 04-2026 о требованиях к продаже тиражей Lotería Nacional и резолюцию 03-2026 об упрощенной процедуре смены владельца, названия, адреса и закрытия пунктов.","b":["Игорный регулятор Доминиканской Республики DGJA в ноябре 2026 года опубликовал две новые резолюции.","Резолюция № 04-2026 от 17 ноября 2026 года, согласно ее названию, устанавливает обязательные требования к продаже тиражей Lotería Nacional через лотерейные пункты (bancas de lotería), агентства и точки продаж.","Резолюция № 03-2026 от 10 ноября 2026 года временно устанавливает требования и упрощенную административную процедуру для смены владельца, смены коммерческого названия, переезда или смены адреса и окончательного закрытия. Она распространяется на лотерейные пункты, пункты спортивных ставок и бинго.","DGJA разместила обе резолюции в виде отсканированных файлов. На страницах новостей указаны только их названия и даты.","Справочно: DGJA издала резолюции 01-2026 и 02-2026 13 октября 2026 года."]}},{"id":"pr-hipico-orders-nov17","reg":"Caribbean","mk":"PR","mkt":"Puerto Rico","auth":"Gaming Commission","cat":"Licensing","date":"2026-11-17","v":"official","brief":true,"t":"Puerto Rico's horse racing bureau lists three new orders, including a $60,000 transport incentive","d":"The Gaming Commission's Horse Racing Bureau has listed orders suspending an article of its racing rules, on Caribbean Series workouts and on an extra $60,000 for horse transport.","b":["The Horse Racing Bureau (Negociado del Deporte Hípico) of the Puerto Rico Gaming Commission has listed three new administrative orders.","Order OACJ-NH-26-17, dated 16 November 2026, suspends Article XXXVI of Horse Racing Regulation No. 8944, according to its title. Order OADE-NH-26-20, of the same date, covers morning workouts for the 2026 Serie Hípica del Caribe.","Order OADE-NH-26-22, dated 17 November 2026, authorises an additional $60,000 to extend the transport incentive for two-year-old horses in training and imported racing-age horses. The money comes from the Fondo Crianza y Mejoramiento.","The listing gives only titles and dates, and the orders are posted as scanned documents.","Background: the bureau listed orders OADE-NH-26-18 and OADE-NH-26-21 on 10 November 2026."],"src":[["Comisión de Juegos de Puerto Rico, Negociado del Deporte Hípico, administrative orders","https://www.comjuegos.pr.gov/negociados/negociado-del-deporte-hipico","o"],["Order OACJ-NH-26-17 (PDF)","https://docs.pr.gov/files/ComJuegos/Negociado%20del%20Deporte%20Hipico/Ordenes%20Administrativas/2026/OACJ-NH-26-17%20-%20Suspension%20Art.%20XXXVI%20Reg.%20Hipico%208944.pdf","o"],["Order OADE-NH-26-20 (PDF)","https://docs.pr.gov/files/ComJuegos/Negociado%20del%20Deporte%20Hipico/Ordenes%20Administrativas/2026/OADE-NH-26-20__Trabajos%20Matinales%20Serie%20Hipica%20del%20Caribe%202026.pdf","o"],["Order OADE-NH-26-22 (PDF)","https://docs.pr.gov/files/ComJuegos/Negociado%20del%20Deporte%20Hipico/Ordenes%20Administrativas/2026/OADE-NH-26-22__%20Incentivo%20(adicional)%20Transporte%20de%20Ejemplares%20(1).pdf","o"]],"es":{"mkt":"Puerto Rico","auth":"Comisión de Juegos","t":"El negociado hípico de Puerto Rico publica tres nuevas órdenes, entre ellas un incentivo de transporte de 60.000 dólares","d":"El Negociado del Deporte Hípico de la Comisión de Juegos ha publicado órdenes que suspenden un artículo de su reglamento hípico, sobre los trabajos de la Serie del Caribe y sobre 60.000 dólares adicionales para el transporte de caballos.","b":["El Negociado del Deporte Hípico de la Comisión de Juegos de Puerto Rico ha publicado tres nuevas órdenes administrativas.","La Orden OACJ-NH-26-17, de 16 de noviembre de 2026, suspende el artículo XXXVI del Reglamento Hípico núm. 8944, según su título. La Orden OADE-NH-26-20, de la misma fecha, trata de los trabajos matinales de la Serie Hípica del Caribe 2026.","La Orden OADE-NH-26-22, de 17 de noviembre de 2026, autoriza 60.000 dólares adicionales para ampliar el incentivo de transporte de ejemplares de dos años en entrenamiento y de ejemplares importados en edad de competir. El dinero sale del Fondo Crianza y Mejoramiento.","La lista solo da títulos y fechas, y las órdenes están publicadas como documentos escaneados.","Antecedentes: el negociado publicó las órdenes OADE-NH-26-18 y OADE-NH-26-21 el 10 de noviembre de 2026."]},"ru":{"mkt":"Пуэрто-Рико","auth":"Игорная комиссия","t":"Бюро скачек Пуэрто-Рико опубликовало три новых приказа, в том числе о транспортной субсидии 60 000 долларов","d":"Бюро скачек Игорной комиссии опубликовало приказы о приостановке статьи правил скачек, о тренировках к Карибской серии и о дополнительных 60 000 долларов на перевозку лошадей.","b":["Бюро скачек (Negociado del Deporte Hípico) Игорной комиссии Пуэрто-Рико опубликовало три новых административных приказа.","Приказ OACJ-NH-26-17 от 16 ноября 2026 года, согласно его названию, приостанавливает статью XXXVI Правил скачек № 8944. Приказ OADE-NH-26-20 от той же даты касается утренних тренировок к Serie Hípica del Caribe 2026.","Приказ OADE-NH-26-22 от 17 ноября 2026 года выделяет дополнительно 60 000 долларов на продление транспортной субсидии для двухлетних лошадей в тренинге и импортных лошадей скакового возраста. Средства поступают из Fondo Crianza y Mejoramiento.","В перечне указаны только названия и даты, приказы размещены в виде отсканированных документов.","Справочно: 10 ноября 2026 года бюро опубликовало приказы OADE-NH-26-18 и OADE-NH-26-21."]}},{"id":"pt-srij-match-fixing-platform","reg":"Europe","mk":"PT","mkt":"Portugal","auth":"SRIJ","cat":"Other","date":"2026-11-16","v":"official","t":"Portugal: national platform against sports match-fixing opens website with reporting channels","d":"The national platform against the manipulation of sports competitions launched a website on 16 November with channels to report suspected manipulation, the gambling regulator SRIJ said.","b":["The national platform against the manipulation of sports competitions launched its website on 16 November 2026, the gaming regulation and inspection service (SRIJ) of Turismo de Portugal said. The site gives information to sports bodies and the public. It also offers dedicated channels to report suspected manipulation of competitions.","The platform was created by Law No. 14/2024 of 19 January as a cooperation mechanism between public and sports bodies. It follows the aims of the Council of Europe Macolin Convention on the manipulation of sports competitions. The National Unit Against Corruption of the Judicial Police coordinates it.","It has nine members: the Judicial Police, the Prosecutor General's Office, the National Anti-Corruption Mechanism, the coordinating committee on anti-money laundering and terrorist financing policy, the Portuguese Institute of Sport and Youth, the Olympic Committee of Portugal, the Portuguese Football Federation, SRIJ and Santa Casa da Misericórdia de Lisboa."],"src":[["SRIJ, Launch of the website of the national platform against the manipulation of sports competitions (16 November 2026)","https://www.srij.turismodeportugal.pt/pt/noticias/lancamento-do-sitio-web-da-plataforma-nacional-contra-manipulacao-de-competicoes","o"],["RTP","https://www.rtp.pt/noticias/pais/pj-lanca-plataforma-digital-de-combate-a-manipulacao-dos-resultados-desportivos_n1779475","p"],["TSF","https://www.tsf.pt/desporto/artigo/lancada-nova-plataforma-digital-para-combater-a-manipulacao-de-competicoes-desportivas/18149432","p"]],"es":{"mkt":"Portugal","auth":"SRIJ","t":"Portugal: la plataforma nacional contra el amaño de competiciones deportivas abre una web con canales de denuncia","d":"La plataforma nacional contra la manipulación de competiciones deportivas lanzó el 16 de noviembre una web con canales para denunciar sospechas de manipulación, según el regulador del juego SRIJ.","b":["La plataforma nacional contra la manipulación de competiciones deportivas lanzó su web el 16 de noviembre de 2026, informó el servicio de regulación e inspección de juegos (SRIJ) de Turismo de Portugal. La web ofrece información a las entidades deportivas y al público. También ofrece canales específicos para denunciar sospechas de manipulación de competiciones.","La plataforma se creó por la Ley n.º 14/2024, de 19 de enero, como mecanismo de cooperación entre entidades públicas y deportivas. Sigue los objetivos del Convenio de Macolin del Consejo de Europa sobre la manipulación de competiciones deportivas. La coordina la Unidad Nacional contra la Corrupción de la Policía Judicial.","Tiene nueve miembros: la Policía Judicial, la Fiscalía General, el Mecanismo Nacional Anticorrupción, la comisión de coordinación de las políticas de prevención del blanqueo de capitales y de la financiación del terrorismo, el Instituto Portugués del Deporte y la Juventud, el Comité Olímpico de Portugal, la Federación Portuguesa de Fútbol, el SRIJ y la Santa Casa da Misericórdia de Lisboa."]},"ru":{"mkt":"Португалия","auth":"SRIJ","t":"Португалия: национальная платформа против договорных матчей открыла сайт с каналами для сообщений","d":"Национальная платформа против манипулирования спортивными соревнованиями 16 ноября запустила сайт с каналами для сообщений о подозрениях в манипулировании, сообщил игорный регулятор SRIJ.","b":["Национальная платформа против манипулирования спортивными соревнованиями 16 ноября 2026 года запустила свой сайт, сообщила служба регулирования и инспекции азартных игр (SRIJ) при Turismo de Portugal. Сайт предоставляет информацию спортивным организациям и общественности. На нем также есть специальные каналы для сообщений о подозрениях в манипулировании соревнованиями.","Платформа создана Законом № 14/2024 от 19 января как механизм сотрудничества государственных и спортивных организаций. Она следует целям Маколинской конвенции Совета Европы о манипулировании спортивными соревнованиями. Ее работу координирует Национальное управление по борьбе с коррупцией Судебной полиции.","В платформу входят девять участников: Судебная полиция, Генеральная прокуратура, Национальный антикоррупционный механизм, координационный комитет по политике ПОД/ФТ, Португальский институт спорта и молодежи, Олимпийский комитет Португалии, Португальская футбольная федерация, SRIJ и Santa Casa da Misericórdia de Lisboa."]}},{"id":"pt-srij-esgw-2026","reg":"Europe","mk":"PT","mkt":"Portugal","auth":"SRIJ","cat":"Safer gambling","date":"2026-11-16","v":"official","t":"Portugal: SRIJ joins European Safer Gambling Week from 16 to 22 November","d":"The Portuguese gambling regulator SRIJ is taking part in the sixth European Safer Gambling Week, which runs from 16 to 22 November.","b":["The gaming regulation and inspection service (SRIJ) said on 16 November 2026 that it is joining European Safer Gambling Week, which runs from 16 to 22 November. This is the sixth edition of the campaign, organised by the European Gaming and Betting Association (EGBA). The theme is \"Play Smart, Stay Protected\".","SRIJ says the campaign urges players to make informed decisions, use the protection tools available and play only with licensed services. It is sharing campaign content on its X account, @SRIJogos."],"src":[["SRIJ, SRIJ joins European Safer Gambling Week 2026 (16 November 2026)","https://www.srij.turismodeportugal.pt/pt/noticias/o-srij-associa-se-european-safer-gambling-week-2026","o"],["Jamma","https://www.jamma.it/mercato/gioco-responsabile-il-regolatore-portoghese-srij-aderisce-alla-european-safer-gambling-week-2026-362753","p"]],"es":{"mkt":"Portugal","auth":"SRIJ","t":"Portugal: el SRIJ se suma a la Semana Europea del Juego más Seguro del 16 al 22 de noviembre","d":"El regulador portugués del juego SRIJ participa en la sexta Semana Europea del Juego más Seguro, que se celebra del 16 al 22 de noviembre.","b":["El servicio de regulación e inspección de juegos (SRIJ) dijo el 16 de noviembre de 2026 que se suma a la European Safer Gambling Week, que se celebra del 16 al 22 de noviembre. Es la sexta edición de la campaña, organizada por la European Gaming and Betting Association (EGBA). El lema es \"Play Smart, Stay Protected\".","El SRIJ dice que la campaña anima a los jugadores a tomar decisiones informadas, usar las herramientas de protección disponibles y jugar solo con servicios con licencia. Comparte contenidos de la campaña en su cuenta de X, @SRIJogos."]},"ru":{"mkt":"Португалия","auth":"SRIJ","t":"Португалия: SRIJ присоединился к Европейской неделе ответственной игры с 16 по 22 ноября","d":"Португальский игорный регулятор SRIJ участвует в шестой Европейской неделе ответственной игры, которая проходит с 16 по 22 ноября.","b":["Служба регулирования и инспекции азартных игр (SRIJ) 16 ноября 2026 года сообщила, что присоединяется к European Safer Gambling Week, которая проходит с 16 по 22 ноября. Это шестая кампания, ее организует European Gaming and Betting Association (EGBA). Девиз кампании \"Play Smart, Stay Protected\".","По словам SRIJ, кампания призывает игроков принимать осознанные решения, пользоваться доступными инструментами защиты и играть только в лицензированных сервисах. Регулятор публикует материалы кампании в своем аккаунте в X, @SRIJogos."]}},{"id":"gb-ni-yp-health-stats-dec","reg":"Europe","mk":"GB","mkt":"United Kingdom","auth":"Department of Health (NI)","cat":"Market data","date":"2026-11-16","v":"official","t":"UK (Northern Ireland): health statistics on young people's gambling also due on 9 December","d":"NISRA and the Department of Health in Northern Ireland will publish a health view of the gambling module of the 2025 Young Persons' Behaviour and Attitudes Survey on 9 December.","b":["The Northern Ireland Statistics and Research Agency (NISRA) and the Department of Health (Northern Ireland) announced on 16 November 2026 a release called \"Young Persons' Behaviour and Attitudes Survey 2025: Gambling, a health perspective\". It is provisionally due on 9 December 2026 at 9:30am.","It will present findings from the gambling module of the 2025 survey. Background: the Department for Communities announced on 10 November a separate release, \"Experience of gambling by young people in Northern Ireland 2025\", for the same day."],"src":[["GOV.UK, Young Persons' Behaviour and Attitudes Survey 2025: Gambling, a health perspective (release announcement)","https://www.gov.uk/government/statistics/announcements/young-persons-behaviour-and-attitudes-survey-2025-gambling-a-health-perspective","o"]],"es":{"mkt":"Reino Unido","auth":"Departamento de Salud (Irlanda del Norte)","t":"Reino Unido (Irlanda del Norte): las estadísticas sanitarias sobre el juego de los jóvenes también se publicarán el 9 de diciembre","d":"NISRA y el Departamento de Salud de Irlanda del Norte publicarán el 9 de diciembre un análisis sanitario del módulo de juego de la encuesta de 2025 sobre conductas y actitudes de los jóvenes.","b":["La Agencia de Estadística e Investigación de Irlanda del Norte (NISRA) y el Departamento de Salud (Irlanda del Norte) anunciaron el 16 de noviembre de 2026 una publicación titulada \"Young Persons' Behaviour and Attitudes Survey 2025: Gambling, a health perspective\". Está prevista, de forma provisional, para el 9 de diciembre de 2026 a las 9:30.","Presentará los resultados del módulo de juego de la encuesta de 2025. Antecedentes: el Departamento de Comunidades anunció el 10 de noviembre otra publicación, \"Experience of gambling by young people in Northern Ireland 2025\", para el mismo día."]},"ru":{"mkt":"Великобритания","auth":"Министерство здравоохранения (Северная Ирландия)","t":"Великобритания (Северная Ирландия): статистика здравоохранения об азартных играх молодежи также выйдет 9 декабря","d":"NISRA и Министерство здравоохранения Северной Ирландии 9 декабря опубликуют анализ модуля об азартных играх из опроса 2025 года о поведении и взглядах молодежи с точки зрения здоровья.","b":["Агентство статистики и исследований Северной Ирландии (NISRA) и Министерство здравоохранения (Северная Ирландия) 16 ноября 2026 года объявили о публикации \"Young Persons' Behaviour and Attitudes Survey 2025: Gambling, a health perspective\". Предварительно она запланирована на 9 декабря 2026 года в 9:30.","В ней будут представлены результаты модуля об азартных играх из опроса 2025 года. Справочно: 10 ноября Министерство по делам общин объявило отдельную публикацию \"Experience of gambling by young people in Northern Ireland 2025\" на тот же день."]}},{"id":"es-rio-budget27-amendment-deadline","reg":"Europe","mk":"ES","mkt":"Spain","auth":"Parlamento de La Rioja","cat":"Legislation","date":"2026-11-16","v":"official","t":"Spain (La Rioja): parliament gives until 4 December to amend the 2027 budget and fiscal measures bills","d":"The Bureau of the Parliament of La Rioja extended the deadline for partial amendments to the 2027 budget bill and the 2027 fiscal and administrative measures bill.","b":["The Bureau of the Parliament of La Rioja decided on 16 November 2026, after hearing the Board of Spokespersons, to extend the deadline for partial amendments to two bills: the 2027 general budget of the region and the 2027 fiscal and administrative measures bill.","Groups can now file partial amendments until 10:00 on 4 December 2026.","Background: On 4 November the plenary rejected the totality amendments to both bills."],"src":[["Parlamento de La Rioja, 16 Nov 2026","https://www.parlamento-larioja.org/comunicacion/noticias/ampliado-el-plazo-de-presentacion-de-enmiendas-parciales-al-proyecto-de-ley-de-presupuestos-generales-de-la-car-hasta-el-4-de-diciembre","o"],["Nuevecuatrouno","https://nuevecuatrouno.com/2026/11/16/el-parlamento-amplia-al-4-de-diciembre-el-plazo-de-enmiendas-a-los-presupuestos","p"]],"es":{"mkt":"España","auth":"Parlamento de La Rioja","t":"España (La Rioja): el Parlamento da hasta el 4 de diciembre para enmendar los proyectos de presupuestos y de medidas fiscales de 2027","d":"La Mesa del Parlamento de La Rioja amplió el plazo de enmiendas parciales al proyecto de presupuestos de 2027 y al proyecto de medidas fiscales y administrativas de 2027.","b":["La Mesa del Parlamento de La Rioja acordó el 16 de noviembre de 2026, oída la Junta de Portavoces, ampliar el plazo de enmiendas parciales a dos proyectos de ley: los presupuestos generales de la comunidad para 2027 y el proyecto de medidas fiscales y administrativas para 2027.","Los grupos pueden presentar enmiendas parciales hasta las 10:00 del 4 de diciembre de 2026.","Antecedentes: el 4 de noviembre el pleno rechazó las enmiendas a la totalidad a ambos proyectos."]},"ru":{"mkt":"Испания","auth":"Parlamento de La Rioja","t":"Испания (Риоха): парламент дал время до 4 декабря на поправки к законопроектам о бюджете и фискальных мерах на 2027 год","d":"Президиум парламента Риохи продлил срок подачи частичных поправок к законопроекту о бюджете на 2027 год и законопроекту о фискальных и административных мерах на 2027 год.","b":["Президиум парламента Риохи 16 ноября 2026 года, заслушав совет представителей фракций, решил продлить срок подачи частичных поправок к двум законопроектам: об общем бюджете региона на 2027 год и о фискальных и административных мерах на 2027 год.","Фракции могут подавать частичные поправки до 10:00 4 декабря 2026 года.","Справочно: 4 ноября пленарное заседание отклонило поправки об отклонении обоих законопроектов в целом."]}},{"id":"br-pb-lotep-romaria-penha-campaign","reg":"Latin America","mk":"BR","mkt":"Brazil (Paraíba)","auth":"Lotep","cat":"Safer gambling","date":"2026-11-16","v":"official","t":"Brazil (Paraíba): state lottery to run responsible gambling campaign at the Romaria da Penha pilgrimage","d":"Lotep will hand out leaflets and put up posters on responsible gambling during the 263rd Romaria de Nossa Senhora da Penha in João Pessoa, 21 to 29 November.","b":["The Paraíba state lottery Lotep said on 16 November 2026 that it will run a responsible gambling awareness action at the 263rd Romaria de Nossa Senhora da Penha in João Pessoa. The festival runs from 21 to 29 November 2026.","Lotep staff will hand out information material and put up posters during the event. The message is that betting should stay a form of recreation and should not put the family budget, financial security or wellbeing at risk. Lotep also reminds the public that Brazilian law bars children and adolescents from betting.","The pilgrimage itself takes place on 28 and 29 November. Pilgrims walk about 14 km from the Igreja de Nossa Senhora de Lourdes in the city centre to the Santuário da Penha, and a mass closes it early on 29 November."],"src":[["Lotep, Lotep promove ação de conscientização sobre jogo responsável durante a Romaria da Penha 2026, 16 Nov 2026","https://lotep.pb.gov.br/noticia/lotep-promove-acao-de-conscientizacao-sobre-jogo-responsavel-durante-a-romaria-da-penha-2026","o"],["BNLData, 17 Nov 2026","https://bnldata.com.br/lotep-promove-acao-de-conscientizacao-sobre-jogo-responsavel-durante-a-romaria-da-penha-2026/","p"]],"es":{"mkt":"Brasil (Paraíba)","auth":"Lotep","t":"Brasil (Paraíba): la lotería estatal hará una campaña de juego responsable en la romería de la Penha","d":"Lotep repartirá folletos y colocará carteles sobre juego responsable durante la 263.ª Romaria de Nossa Senhora da Penha en João Pessoa, del 21 al 29 de noviembre.","b":["La lotería del estado de Paraíba, Lotep, dijo el 16 de noviembre de 2026 que hará una acción de concienciación sobre juego responsable en la 263.ª Romaria de Nossa Senhora da Penha en João Pessoa. La fiesta se celebra del 21 al 29 de noviembre de 2026.","El personal de Lotep repartirá material informativo y colocará carteles durante el evento. El mensaje es que apostar debe seguir siendo una forma de ocio y no debe poner en riesgo el presupuesto familiar, la seguridad financiera ni el bienestar. Lotep recuerda también que la ley brasileña prohíbe apostar a niños y adolescentes.","La romería propiamente dicha se celebra el 28 y el 29 de noviembre. Los peregrinos caminan unos 14 km desde la Igreja de Nossa Senhora de Lourdes, en el centro de la ciudad, hasta el Santuário da Penha, y una misa la cierra de madrugada el 29 de noviembre."]},"ru":{"mkt":"Бразилия (Параиба)","auth":"Lotep","t":"Бразилия (Параиба): лотерея штата проведет кампанию за ответственную игру во время паломничества Ромария-да-Пенья","d":"Lotep будет раздавать листовки и размещать плакаты об ответственной игре во время 263-го паломничества Romaria de Nossa Senhora da Penha в Жуан-Песоа с 21 по 29 ноября.","b":["Лотерея штата Параиба Lotep 16 ноября 2026 года сообщила, что проведет акцию по информированию об ответственной игре во время 263-го паломничества Romaria de Nossa Senhora da Penha в Жуан-Песоа. Праздник проходит с 21 по 29 ноября 2026 года.","Сотрудники Lotep будут раздавать информационные материалы и размещать плакаты во время мероприятия. Главная мысль акции: ставки должны оставаться развлечением и не должны ставить под угрозу семейный бюджет, финансовую безопасность или благополучие. Lotep также напоминает, что бразильский закон запрещает ставки детям и подросткам.","Само паломничество пройдет 28 и 29 ноября. Паломники проходят около 14 км от церкви Igreja de Nossa Senhora de Lourdes в центре города до Santuário da Penha, завершает паломничество месса рано утром 29 ноября."]}},{"id":"za-ec-ecgb-machines-destroyed","reg":"Africa","mk":"ZA","mkt":"South Africa (Eastern Cape)","auth":"NGB","cat":"Enforcement","date":"2026-11-16","v":"official","t":"South Africa (Eastern Cape): provincial gambling board destroys more than 300 illegal gambling machines","d":"The National Gambling Board says the Eastern Cape Gambling Board destroyed more than 300 illegal machines as part of ongoing enforcement.","b":["The Eastern Cape Gambling Board has destroyed more than 300 illegal gambling machines, the National Gambling Board (NGB) said on its official social media account on 16 November 2026. The NGB said the destruction is part of ongoing enforcement work and that the provincial board continues to step up its efforts against illegal gambling.","Trade outlets put the number at 314 machines, destroyed in East London. The NGB post does not give an exact figure or a place.","The Eastern Cape board's own news page carries no item on the destruction. Background: the board destroyed more than 500 machines in October 2025."],"src":[["National Gambling Board, official post of 16 Nov 2026 (shown on its homepage)","https://www.ngb.org.za/","o"],["Focus Gaming News","https://focusgn.com/africa/eastern-cape-illegal-gambling-machines","p"],["iGaming Afrika, 17 Nov 2026","https://igamingafrika.com/eastern-cape-gambling-board-destroys-314-illegal-gambling-machines/","p"]],"es":{"mkt":"Sudáfrica (Cabo Oriental)","auth":"NGB","t":"Sudáfrica (Cabo Oriental): la junta provincial del juego destruye más de 300 máquinas de juego ilegales","d":"La Junta Nacional del Juego dice que la Junta del Juego del Cabo Oriental destruyó más de 300 máquinas ilegales dentro de su labor de control.","b":["La Junta del Juego del Cabo Oriental ha destruido más de 300 máquinas de juego ilegales, dijo la Junta Nacional del Juego (NGB) en su cuenta oficial en redes sociales el 16 de noviembre de 2026. La NGB dijo que la destrucción forma parte de la labor de control en curso y que la junta provincial sigue reforzando su lucha contra el juego ilegal.","Medios del sector cifran en 314 las máquinas destruidas, en East London. La publicación de la NGB no da una cifra exacta ni un lugar.","La página de noticias de la junta del Cabo Oriental no recoge la destrucción. Antecedentes: la junta destruyó más de 500 máquinas en octubre de 2025."]},"ru":{"mkt":"ЮАР (Восточная Капская провинция)","auth":"NGB","t":"ЮАР (Восточная Капская провинция): провинциальный игорный совет уничтожил более 300 незаконных игровых автоматов","d":"Национальный игорный совет сообщил, что Игорный совет Восточной Капской провинции уничтожил более 300 незаконных автоматов в рамках текущей работы по надзору.","b":["Игорный совет Восточной Капской провинции уничтожил более 300 незаконных игровых автоматов, сообщил Национальный игорный совет (NGB) в официальном аккаунте в соцсетях 16 ноября 2026 года. По словам NGB, уничтожение входит в текущую работу по надзору, а провинциальный совет продолжает усиливать борьбу с незаконными азартными играми.","Отраслевые издания называют число 314 автоматов, уничтоженных в Ист-Лондоне. В публикации NGB точное число и место не указаны.","На странице новостей совета Восточной Капской провинции сообщения об уничтожении нет. Справочно: в октябре 2025 года совет уничтожил более 500 автоматов."]}},{"id":"do-dgja-nov23","reg":"Caribbean","mk":"DO","mkt":"Dominican Republic","auth":"DGJA","cat":"Licensing","date":"2026-11-13","v":"official","t":"Dominican regulator extends the deadline to declare unregistered betting outlets to 23 November","d":"The DGJA has extended the extraordinary period for declaring outlets outside its regularisation plan from 15 November to 23 November 2026.","b":["The Dominican gambling regulator DGJA has moved the deadline for declaring outlets left out of its regularisation plan to Monday 23 November 2026. It announced the change in a notice dated 13 November 2026.","The extraordinary period was set under Resolución núm. 02-2026 and was due to end on 15 November 2026. It covers owners and operators of lottery outlets (bancas de lotería), sports betting outlets and other gambling establishments that did not join the Plan de Regularización.","The DGJA says the extra time lets owners and operators file their declaration and update their data. Information and requirements are on a Lotería Nacional web form. In-person queries go to the DGJA offices in the Lotería Nacional building in the Distrito Nacional, Monday to Friday, 8:00 to 16:00.","Background: on 2 November the DGJA said a declaration does not give permission to operate."],"src":[["DGJA, extension of the extraordinary period to 23 November 2026, 13 Nov 2026","https://dgja.gob.do/noticias/direccion-general-de-juegos-de-azar-extiende-plazo-extraordinario-para-declarar-los-establecimientos-que-quedaron-fuera-del-plan-de-regularizacion-hasta-el-lunes-23-de-noviembre-de-2026/","o"],["DGJA news list","https://dgja.gob.do/noticias/","o"]],"es":{"mkt":"República Dominicana","auth":"DGJA","t":"El regulador dominicano amplía hasta el 23 de noviembre el plazo para declarar puntos de apuestas no registrados","d":"La DGJA ha ampliado del 15 al 23 de noviembre de 2026 el plazo extraordinario para declarar los establecimientos que quedaron fuera de su plan de regularización.","b":["El regulador dominicano del juego, la DGJA, ha trasladado al lunes 23 de noviembre de 2026 el plazo para declarar los establecimientos que quedaron fuera de su plan de regularización. Anunció el cambio en un aviso fechado el 13 de noviembre de 2026.","El plazo extraordinario se fijó con la Resolución núm. 02-2026 y debía terminar el 15 de noviembre de 2026. Abarca a propietarios y operadores de bancas de lotería, bancas de apuestas deportivas y otros establecimientos de juego que no se acogieron al Plan de Regularización.","La DGJA dice que el tiempo adicional permite a propietarios y operadores presentar su declaración y actualizar sus datos. La información y los requisitos están en un formulario web de la Lotería Nacional. Las consultas presenciales se atienden en las oficinas de la DGJA en el edificio de la Lotería Nacional, en el Distrito Nacional, de lunes a viernes de 8:00 a 16:00.","Antecedentes: el 2 de noviembre la DGJA dijo que una declaración no da permiso para operar."]},"ru":{"mkt":"Доминиканская Республика","auth":"DGJA","t":"Доминиканский регулятор продлил до 23 ноября срок декларирования незарегистрированных пунктов ставок","d":"DGJA продлила чрезвычайный срок декларирования заведений, не вошедших в план упорядочения, с 15 до 23 ноября 2026 года.","b":["Игорный регулятор Доминиканской Республики DGJA перенес срок декларирования заведений, не вошедших в план упорядочения, на понедельник 23 ноября 2026 года. Об изменении он объявил в уведомлении от 13 ноября 2026 года.","Чрезвычайный срок был установлен резолюцией № 02-2026 и должен был истечь 15 ноября 2026 года. Он распространяется на владельцев и операторов лотерейных пунктов (bancas de lotería), пунктов спортивных ставок и других игорных заведений, не присоединившихся к Plan de Regularización.","По словам DGJA, дополнительное время позволяет владельцам и операторам подать декларацию и обновить данные. Информация и требования размещены в веб-форме Lotería Nacional. Очные консультации проводятся в офисах DGJA в здании Lotería Nacional в Национальном округе с понедельника по пятницу с 8:00 до 16:00.","Справочно: 2 ноября DGJA заявила, что декларация не дает права на работу."]}},{"id":"br-pr-lottopar-wlc-second-commission","reg":"Latin America","mk":"BR","mkt":"Brazil (Paraná)","auth":"Lottopar","cat":"Enforcement","date":"2026-11-12","v":"official","t":"Brazil (Paraná): state lottery opens a second administrative process against WLC Paraná","d":"Lottopar Ordinance 073/2026 sets up a new commission on the concessionaire under Contract 018/2023 and cites the betting ban measure as the reason.","b":["The Paraná state lottery Lottopar signed Ordinance (Portaria) 073/2026 in Curitiba on 12 November 2026. It sets up a three-member commission to run an administrative process against WLC Paraná Exploração de Jogos e Apostas SPE Ltda under Contract 018/2023.","Article 1 names Provisional Measure 1.394/2026, which bans fixed-odds betting, as the reason for the process. It says the company is subject to the penalties in the laws cited, the contract and Lottopar rules. The legal basis is federal procurement Law 14.133/2021 and Paraná Decree 10.086/2022. The commission has 30 days to finish, and the act took effect on publication.","Lottopar's operator list links Contract 018/2023 to the ParanaBet brand. The same page says fixed-odds betting in Paraná is suspended under Provisional Measure 1.394 and that the register is kept as a record.","Background: Lottopar opened a first process against WLC Paraná with Ordinance 068/2026 on 3 November, and on 12 November signed Ordinances 072/2026 and 074/2026 against two other concessionaires."],"src":[["Lottopar, Portaria 073/2026, 12 Nov 2026","https://www.lottopar.pr.gov.br/sites/default/arquivos_restritos/files/documento/2026-11/portaria_073.2026_-_designa_a_comissao_de_processo_administrativo_em_face_da_wlc_parana.pdf","o"],["Lottopar, Portarias","https://www.lottopar.pr.gov.br/Pagina/Portarias","o"],["Lottopar, authorised fixed-odds operators","https://www.lottopar.pr.gov.br/Pagina/Operadores-Autorizados-Aposta-de-Quota-Fixa","o"]],"es":{"mkt":"Brasil (Paraná)","auth":"Lottopar","t":"Brasil (Paraná): la lotería estatal abre un segundo procedimiento administrativo contra WLC Paraná","d":"La Portaria 073/2026 de Lottopar crea una nueva comisión sobre la concesionaria del Contrato 018/2023 y cita como motivo la medida de prohibición de las apuestas.","b":["La lotería del estado de Paraná, Lottopar, firmó en Curitiba el 12 de noviembre de 2026 la Portaria 073/2026. Crea una comisión de tres miembros para llevar un procedimiento administrativo contra WLC Paraná Exploração de Jogos e Apostas SPE Ltda en el marco del Contrato 018/2023.","El artículo 1 cita la Medida Provisional 1.394/2026, que prohíbe las apuestas de cuota fija, como motivo del procedimiento. Dice que la empresa está sujeta a las sanciones de las leyes citadas, del contrato y de las normas de Lottopar. La base legal es la Ley federal de contratación 14.133/2021 y el Decreto 10.086/2022 de Paraná. La comisión tiene 30 días para terminar, y el acto entró en vigor con su publicación.","La lista de operadores de Lottopar vincula el Contrato 018/2023 a la marca ParanaBet. La misma página dice que las apuestas de cuota fija en Paraná están suspendidas por la Medida Provisional 1.394 y que el registro se mantiene como constancia.","Antecedentes: Lottopar abrió un primer procedimiento contra WLC Paraná con la Portaria 068/2026 el 3 de noviembre, y el 12 de noviembre firmó las Portarias 072/2026 y 074/2026 contra otras dos concesionarias."]},"ru":{"mkt":"Бразилия (Парана)","auth":"Lottopar","t":"Бразилия (Парана): лотерея штата начала второе административное производство против WLC Paraná","d":"Распоряжение Lottopar 073/2026 создает новую комиссию по концессионеру по контракту 018/2023 и называет причиной меру о запрете ставок.","b":["Лотерея штата Парана Lottopar 12 ноября 2026 года подписала в Куритибе распоряжение (Portaria) 073/2026. Оно создает комиссию из трех человек для ведения административного производства против WLC Paraná Exploração de Jogos e Apostas SPE Ltda по контракту 018/2023.","В статье 1 причиной производства названа временная мера 1.394/2026, запрещающая ставки с фиксированными коэффициентами. В ней говорится, что к компании применимы санкции по указанным законам, контракту и правилам Lottopar. Правовая основа: федеральный закон о закупках 14.133/2021 и декрет штата Парана 10.086/2022. У комиссии есть 30 дней, акт вступил в силу с момента публикации.","В списке операторов Lottopar контракт 018/2023 связан с брендом ParanaBet. На той же странице указано, что ставки с фиксированными коэффициентами в Паране приостановлены по временной мере 1.394, а реестр сохраняется для учета.","Справочно: Lottopar начала первое производство против WLC Paraná распоряжением 068/2026 3 ноября, а 12 ноября подписала распоряжения 072/2026 и 074/2026 против двух других концессионеров."]}},{"id":"za-ngb-rg-month-statement","reg":"Africa","mk":"ZA","mkt":"South Africa","auth":"National Gambling Board","cat":"Safer gambling","date":"2026-11-12","v":"official","t":"South Africa: National Gambling Board puts 2025/26 gambling revenue at R84.5 billion and asks provinces to enforce ban on ads aimed at minors","d":"In a Responsible Gambling Month statement the board says betting made up 74% of revenue and asks regulators and internet providers to act against illegal gambling.","b":["The National Gambling Board (NGB) said in a media statement on 12 November 2026 that South Africa's gambling turnover reached R1.8 trillion in 2025/26. Gross gambling revenue was about R84.5 billion. Betting made up 74% of it, at R62.2 billion, up 19.6% on the year before.","The board asked provincial licensing authorities to enforce the National Gambling Act's ban on advertising aimed at minors or that appeals to them, and to act against operators that do not comply. It asked internet service providers to cooperate more in blocking illegal gambling sites. It told the public to check operators on its Verified Gambling Operators Web-Portal.","In the first six months of 2026/27, the statement says, 7 illegal machines were confiscated and 4 criminal cases opened in KwaZulu-Natal. In Limpopo, operations in Modimolle and Lephalale led to 13 arrests and R10 853.10 in cash seized. The board identified 43 suspected illegal gambling websites.","The NGB, the South African Responsible Gambling Foundation and the Eastern Cape Gambling Board also visited Golden Palace in Port St Johns on 11 November and a bingo hall in Mthatha on 12 November to raise awareness, the NGB said on its official account. Background: the NGB marked November as National Responsible Gambling Month on 2 November."],"src":[["National Gambling Board, media statement, 12 Nov 2026","https://www.ngb.org.za/wp-content/uploads/2026/11/MEDIA-STATEMENT_NGB-NATIONAL-RESPONSIBLE-GAMBLING-MONTH_12-NOVEMBER-2026.pdf","o"],["National Gambling Board, news page","https://www.ngb.org.za/latest-news/the-national-gambling-board-marks-national-responsible-gambling-month-calls-for-greater-player-protection-and-public-awareness/","o"],["National Gambling Board, homepage with official posts of 11 and 12 Nov 2026","https://www.ngb.org.za/","o"]],"es":{"mkt":"Sudáfrica","auth":"Junta Nacional del Juego","t":"Sudáfrica: la Junta Nacional del Juego cifra los ingresos del juego de 2025/26 en 84.500 millones de rands y pide a las provincias aplicar la prohibición de anuncios dirigidos a menores","d":"En un comunicado por el Mes del Juego Responsable, la junta dice que las apuestas supusieron el 74% de los ingresos y pide a los reguladores y a los proveedores de internet que actúen contra el juego ilegal.","b":["La Junta Nacional del Juego (NGB) dijo en un comunicado el 12 de noviembre de 2026 que el volumen de juego en Sudáfrica alcanzó 1,8 billones de rands en 2025/26. Los ingresos brutos del juego fueron de unos 84.500 millones de rands. Las apuestas supusieron el 74%, con 62.200 millones de rands, un 19,6% más que el año anterior.","La junta pidió a las autoridades provinciales de licencias que apliquen la prohibición de la Ley Nacional del Juego de la publicidad dirigida a menores o que les atraiga, y que actúen contra los operadores que no cumplan. Pidió a los proveedores de servicios de internet más cooperación para bloquear las webs de juego ilegal. Pidió al público que compruebe a los operadores en su portal Verified Gambling Operators Web-Portal.","En los seis primeros meses de 2026/27, según el comunicado, se confiscaron 7 máquinas ilegales y se abrieron 4 causas penales en KwaZulu-Natal. En Limpopo, operaciones en Modimolle y Lephalale llevaron a 13 detenciones y a la incautación de 10.853,10 rands en efectivo. La junta identificó 43 presuntas webs de juego ilegal.","La NGB, la South African Responsible Gambling Foundation y la Junta del Juego del Cabo Oriental visitaron además Golden Palace, en Port St Johns, el 11 de noviembre y una sala de bingo en Mthatha el 12 de noviembre para hacer concienciación, dijo la NGB en su cuenta oficial. Antecedentes: la NGB declaró noviembre Mes Nacional del Juego Responsable el 2 de noviembre."]},"ru":{"mkt":"ЮАР","auth":"Национальный игорный совет","t":"ЮАР: Национальный игорный совет оценил игорный доход за 2025/26 год в 84,5 млрд рэндов и призвал провинции соблюдать запрет рекламы для несовершеннолетних","d":"В заявлении к Месяцу ответственной игры совет сообщил, что на ставки пришлось 74% дохода, и призвал регуляторов и интернет-провайдеров принимать меры против незаконных азартных игр.","b":["Национальный игорный совет (NGB) в заявлении для СМИ 12 ноября 2026 года сообщил, что оборот азартных игр в ЮАР в 2025/26 году достиг 1,8 трлн рэндов. Валовой игорный доход (GGR) составил около 84,5 млрд рэндов. На ставки пришлось 74%, или 62,2 млрд рэндов, что на 19,6% больше, чем годом ранее.","Совет призвал провинциальные лицензирующие органы обеспечить соблюдение запрета Национального закона об азартных играх на рекламу, направленную на несовершеннолетних или привлекательную для них, и принимать меры против нарушителей. Он призвал интернет-провайдеров активнее сотрудничать в блокировке незаконных игорных сайтов. Гражданам рекомендовано проверять операторов на портале Verified Gambling Operators Web-Portal.","Согласно заявлению, за первые шесть месяцев 2026/27 года в провинции Квазулу-Натал изъяты 7 незаконных игровых автоматов и возбуждены 4 уголовных дела. В провинции Лимпопо операции в Модимолле и Лепхалале привели к 13 арестам и изъятию 10 853,10 рэнда наличными. Совет выявил 43 предположительно незаконных игорных сайта.","NGB, South African Responsible Gambling Foundation и Игорный совет Восточной Капской провинции также посетили Golden Palace в Порт-Сент-Джонсе 11 ноября и бинго-зал в Мтате 12 ноября в рамках информационной кампании, сообщил NGB в официальном аккаунте. Справочно: 2 ноября NGB объявил ноябрь Национальным месяцем ответственной игры."]}},{"id":"lt-finmin-progressive-tax-draft","reg":"Europe","mk":"LT","mkt":"Lithuania","auth":"Ministry of Finance","cat":"Tax","date":"2026-11-11","v":"official","t":"Lithuania: finance ministry drafts progressive gambling tax of 22% to 36% and a higher lottery tax","d":"Lithuania's finance ministry registered draft changes that would tax gross gambling revenue at 22%, 29% and 36% by band and raise the lottery tax from 18% to 20%.","b":["Lithuania's Ministry of Finance registered draft amendments to the Law on Lottery and Gambling Tax, the public broadcaster LRT reported on 11 November 2026, carrying a report from the national news agency ELTA. The proposal follows a decision of the ruling coalition council.","The gambling tax would become progressive on gross gambling revenue. The rate would be 22% on revenue up to EUR 3 million, 29% on revenue from EUR 3 million to EUR 5 million and 36% above EUR 5 million. Each higher rate applies only to the revenue above its threshold.","The lottery tax would rise from 18% to 20%, and lottery organisers would move to a quarterly tax period. Gambling organisers would pay quarterly advances and recalculate the tax on annual revenue after the year ends.","The changes would take effect on 1 July 2027, from the third quarter calculation for gambling organisers. The ministry plans to send the draft to the government with the revised 2027 to 2029 budget. On 17 November the national Olympic committee said the lottery change would cost the lottery operator about EUR 2.5 million a year and cut the committee's dividend income by about EUR 1.3 million."],"src":[["LRT (ELTA), ministry proposes progressive gambling tax, 11 Nov 2026","https://www.lrt.lt/naujienos/verslas/4/3111312/ministerija-siulo-ivesti-progresini-losimu-mokesti-didziausias-tarifas-siektu-36-proc","o"],["LRT, Olympic committee on the lottery tax rise, 17 Nov 2026","https://www.lrt.lt/naujienos/sportas/10/3117196/ltok-padidinus-loteriju-mokesti-sporto-finansavimas-mazetu-1-3-mln-euru","o"],["TV3","https://www.tv3.lt/naujiena/verslas/tomilinas-progresinis-losimu-mokestis-biudzeta-papildytu-36-mln-euru-n1565939","p"]],"es":{"mkt":"Lituania","auth":"Ministerio de Finanzas","t":"Lituania: el Ministerio de Finanzas prepara un impuesto progresivo sobre el juego del 22% al 36% y una subida del impuesto sobre loterías","d":"El Ministerio de Finanzas de Lituania registró un proyecto de cambios que gravaría los ingresos brutos del juego al 22%, 29% y 36% por tramos y subiría el impuesto sobre loterías del 18% al 20%.","b":["El Ministerio de Finanzas de Lituania registró un proyecto de enmiendas a la Ley del Impuesto sobre Loterías y Juego, informó la radiotelevisión pública LRT el 11 de noviembre de 2026, con información de la agencia nacional de noticias ELTA. La propuesta sigue una decisión del consejo de la coalición de gobierno.","El impuesto sobre el juego pasaría a ser progresivo sobre los ingresos brutos del juego. El tipo sería del 22% sobre los ingresos de hasta 3 millones de euros, del 29% sobre los ingresos de 3 a 5 millones de euros y del 36% por encima de 5 millones de euros. Cada tipo superior se aplica solo a los ingresos por encima de su umbral.","El impuesto sobre loterías subiría del 18% al 20%, y los organizadores de loterías pasarían a un periodo impositivo trimestral. Los organizadores de juego pagarían anticipos trimestrales y recalcularían el impuesto sobre los ingresos anuales al cierre del año.","Los cambios entrarían en vigor el 1 de julio de 2027, a partir del cálculo del tercer trimestre para los organizadores de juego. El ministerio prevé enviar el proyecto al Gobierno junto con el presupuesto revisado de 2027 a 2029. El 17 de noviembre el comité olímpico nacional dijo que el cambio en las loterías costaría al operador de loterías unos 2,5 millones de euros al año y reduciría los dividendos del comité en unos 1,3 millones de euros."]},"ru":{"mkt":"Литва","auth":"Министерство финансов","t":"Литва: министерство финансов готовит прогрессивный налог на азартные игры от 22% до 36% и повышение налога на лотереи","d":"Министерство финансов Литвы зарегистрировало проект изменений, по которому валовой доход от азартных игр облагался бы по ставкам 22%, 29% и 36% в зависимости от диапазона, а налог на лотереи вырос бы с 18% до 20%.","b":["Министерство финансов Литвы зарегистрировало проект поправок к Закону о налоге на лотереи и азартные игры, сообщила 11 ноября 2026 года общественная телерадиокомпания LRT со ссылкой на национальное агентство ELTA. Предложение следует решению совета правящей коалиции.","Налог на азартные игры станет прогрессивным и будет взиматься с валового дохода от азартных игр. Ставка составит 22% с дохода до 3 млн евро, 29% с дохода от 3 млн до 5 млн евро и 36% с дохода свыше 5 млн евро. Каждая повышенная ставка применяется только к доходу сверх соответствующего порога.","Налог на лотереи вырастет с 18% до 20%, а организаторы лотерей перейдут на квартальный налоговый период. Организаторы азартных игр будут платить ежеквартальные авансы и пересчитывать налог по годовому доходу после окончания года.","Изменения вступят в силу 1 июля 2027 года, начиная с расчета за третий квартал для организаторов азартных игр. Министерство планирует направить проект в правительство вместе с пересмотренным бюджетом на период с 2027 по 2029 год. 17 ноября национальный олимпийский комитет заявил, что изменение для лотерей обойдется лотерейному оператору примерно в 2,5 млн евро в год и сократит дивидендный доход комитета примерно на 1,3 млн евро."]}},{"id":"ph-pagcor-ndrp-advisory","reg":"Asia","mk":"PH","mkt":"Philippines","auth":"PAGCOR","cat":"Responsible gambling","date":"2026-11-11","v":"official","t":"Philippines: PAGCOR checks an online post said to hold data from its restricted persons database","d":"The regulator's cyber response team is checking whether the alleged disclosure is real and whether it links to an earlier incident.","b":["The Philippine Amusement and Gaming Corporation (PAGCOR) said in a public advisory on 11 November that it is aware of a recent online posting that allegedly contains information linked to its National Database of Restricted Persons (NDRP).","Its Computer Emergency Response Team, PAGCOR-CERT, is checking the authenticity, source and extent of the alleged disclosure. That includes whether it relates to a previously reported incident. The advisory calls it an alleged disclosure and gives no further detail."],"src":[["PAGCOR, Public advisory: On the alleged online disclosure of NDRP information, 11 Nov 2026","https://www.pagcor.ph/index.php/docs/headlines/headlines/headlines/public-advisory-for-publication-and-display-on-pagcor-website.html","o"],["iGaming Expert","https://igamingexpert.com/regions/asia/pagcor-alleged-restricted-persons-leak/","p"],["Focus Gaming News","https://focusgn.com/asia-pacific/pagcor-ndrp-data-disclosure","p"]],"es":{"mkt":"Filipinas","auth":"PAGCOR","t":"Filipinas: PAGCOR examina una publicación en internet que contendría datos de su base de personas restringidas","d":"El equipo de respuesta cibernética del regulador comprueba si la presunta filtración es real y si está ligada a un incidente anterior.","b":["La Philippine Amusement and Gaming Corporation (PAGCOR) dijo en un aviso público el 11 de noviembre que tiene conocimiento de una publicación reciente en internet que contendría información vinculada a su Base Nacional de Datos de Personas Restringidas (NDRP).","Su Equipo de Respuesta a Emergencias Informáticas, PAGCOR-CERT, comprueba la autenticidad, el origen y el alcance de la presunta filtración. Eso incluye si guarda relación con un incidente ya comunicado. El aviso la califica de presunta filtración y no da más detalles."]},"ru":{"mkt":"Филиппины","auth":"PAGCOR","t":"Филиппины: PAGCOR проверяет публикацию в интернете, якобы содержащую данные из базы лиц с ограничениями","d":"Группа реагирования регулятора на киберинциденты проверяет, подлинна ли предполагаемая утечка и связана ли она с прежним инцидентом.","b":["Philippine Amusement and Gaming Corporation (PAGCOR) в публичном уведомлении 11 ноября сообщила, что ей известно о недавней публикации в интернете, которая предположительно содержит сведения из ее Национальной базы данных лиц с ограничениями (NDRP).","Ее группа реагирования на компьютерные инциденты PAGCOR-CERT проверяет подлинность, источник и масштаб предполагаемого раскрытия данных, в том числе связь с ранее сообщенным инцидентом. В уведомлении это названо предполагаемым раскрытием, других подробностей нет."]}},{"id":"kz-afm-191bn-terminals-court","reg":"Europe","mk":"KZ","mkt":"Kazakhstan","auth":"Financial Monitoring Agency","cat":"Enforcement","date":"2026-11-09","v":"official","t":"Kazakhstan: financial monitoring agency sends to court a case over 191 billion tenge paid to online casinos through bank terminals","d":"Kazakhstan's Financial Monitoring Agency finished investigating a scheme that moved 191 billion tenge to foreign online casinos through three controlled companies and sent the case to court.","b":["Kazakhstan's Financial Monitoring Agency (AFM) said on 9 November 2026 that it had finished investigating a scheme that took payments for foreign online casinos and had sent the criminal case to court.","Payments ran through the payment infrastructure of three companies under the suspects' control, including hundreds of terminals installed at different banks. Transactions totalled 191 billion tenge, and the commission is put at 286 million tenge. The casinos named are Nomadgames, Sultangames, Pinco, Pin-UP, Vavada, Mostbet and 1WIN.","The details of companies and sole proprietors were used to disguise the payments, some without their knowledge, along with fake contracts and purpose-built websites. Funds went abroad, partly in cryptocurrency.","The organiser was detained. With court approval, four vehicles and 103 million tenge in cash were frozen. Background: this is a separate case from the 188 billion tenge case the AFM sent to court on 29 October."],"src":[["AFM, 191 billion tenge case sent to court, 9 Nov 2026","https://www.gov.kz/org/afm/press/news/details/1325678?lang=kk","o"],["24KZ (Khabar), AFM completes investigation, 9 Nov 2026","https://24.kz/ru/news/incidents/804711-191-mlrd-tenge-cherez-internet-kazino-afm-zavershilo-rassledovanie","o"],["Zakon.kz","https://www.zakon.kz/sobytiia/6537962-191-mlrd-tenge-utekli-iz-kazakhstana-po-delu-internetkazino-arestovali-avtomobili-i-103-mln-nalichnymi.html","p"]],"es":{"mkt":"Kazajistán","auth":"Agencia de Supervisión Financiera","t":"Kazajistán: la agencia de supervisión financiera lleva a juicio un caso de 191.000 millones de tenges pagados a casinos online mediante terminales bancarios","d":"La Agencia de Supervisión Financiera de Kazajistán terminó la investigación de un esquema que movió 191.000 millones de tenges a casinos online extranjeros a través de tres empresas controladas y llevó el caso a los tribunales.","b":["La Agencia de Supervisión Financiera de Kazajistán (AFM) dijo el 9 de noviembre de 2026 que había terminado la investigación de un esquema que cobraba pagos para casinos online extranjeros y que había remitido la causa penal al tribunal.","Los pagos pasaban por la infraestructura de pago de tres empresas bajo control de los sospechosos, incluidos cientos de terminales instalados en distintos bancos. Las transacciones sumaron 191.000 millones de tenges, y la comisión se cifra en 286 millones de tenges. Los casinos citados son Nomadgames, Sultangames, Pinco, Pin-UP, Vavada, Mostbet y 1WIN.","Para ocultar los pagos se usaron los datos de empresas y empresarios individuales, algunos sin su conocimiento, junto con contratos falsos y webs creadas para ello. Los fondos salieron al exterior, en parte en criptomonedas.","El organizador fue detenido. Con autorización judicial se bloquearon cuatro vehículos y 103 millones de tenges en efectivo. Antecedentes: es un caso distinto del de 188.000 millones de tenges que la AFM llevó a juicio el 29 de octubre."]},"ru":{"mkt":"Казахстан","auth":"Агентство по финансовому мониторингу","t":"Казахстан: АФМ направило в суд дело о 191 млрд тенге, переведенных онлайн-казино через банковские терминалы","d":"Агентство по финансовому мониторингу Казахстана завершило расследование схемы, по которой через три подконтрольные компании в зарубежные онлайн-казино ушло 191 млрд тенге, и направило дело в суд.","b":["Агентство по финансовому мониторингу Казахстана (АФМ) 9 ноября 2026 года сообщило, что завершило расследование схемы приема платежей для зарубежных онлайн-казино и направило уголовное дело в суд.","Платежи проходили через платежную инфраструктуру трех компаний, подконтрольных подозреваемым, включая сотни терминалов, установленных в разных банках. Сумма транзакций составила 191 млрд тенге, комиссия оценивается в 286 млн тенге. Названы казино Nomadgames, Sultangames, Pinco, Pin-UP, Vavada, Mostbet и 1WIN.","Для маскировки платежей использовались реквизиты компаний и индивидуальных предпринимателей, часть из них без их ведома, а также фиктивные договоры и специально созданные сайты. Средства выводились за рубеж, частично в криптовалюте.","Организатор задержан. С санкции суда арестованы четыре автомобиля и 103 млн тенге наличными. Справочно: это отдельное дело от дела на 188 млрд тенге, которое АФМ направило в суд 29 октября."]}},{"id":"it-masaf-racecourse-class-2027","reg":"Europe","mk":"IT","mkt":"Italy","auth":"Masaf","cat":"Other","date":"2026-10-31","v":"official","t":"Italy: agriculture ministry ranks 20 trotting and 14 flat racecourses for 2027","d":"A Masaf decree of 31 October updates the classification of Italian racecourses for 2027, with Torino Stupinigi and Milano San Siro at the top.","b":["Italy's agriculture ministry (Masaf) has updated the classification of racecourses for 2027. Directorial decree no. 598837 of 31 October 2026 covers the tracks that were active on that date.","The classification, set out in Annex A, lists 20 trotting tracks and 14 flat racing tracks. Torino Stupinigi heads the trotting list, ahead of Bologna Arcoveggio and Napoli Agnano. Milano San Siro heads the flat list, ahead of Siracusa del Mediterraneo and Roma Capannelle.","The ministry applied the criteria of a decree of 6 December 2024. The file on the ministry site also holds the explanatory report, the criteria sheets and a classification report by the University of Naples Parthenope."],"src":[["Masaf, D.D.G. n. 598837 of 31 Oct 2026","https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/25484","o"],["Jamma","https://www.jamma.it/ippica/ippodromi-il-masaf-aggiorna-la-classificazione-per-il-2027-20-strutture-per-il-trotto-e-14-per-il-galoppo-362932","p"]],"es":{"mkt":"Italia","auth":"Masaf","t":"Italia: el Ministerio de Agricultura clasifica 20 hipódromos de trote y 14 de galope para 2027","d":"Un decreto del Masaf de 31 de octubre actualiza la clasificación de los hipódromos italianos para 2027, con Torino Stupinigi y Milano San Siro a la cabeza.","b":["El Ministerio de Agricultura de Italia (Masaf) ha actualizado la clasificación de los hipódromos para 2027. El decreto directorial n.º 598837, de 31 de octubre de 2026, abarca las pistas activas en esa fecha.","La clasificación, recogida en el anexo A, incluye 20 pistas de trote y 14 de galope. Torino Stupinigi encabeza la lista de trote, por delante de Bologna Arcoveggio y Napoli Agnano. Milano San Siro encabeza la de galope, por delante de Siracusa del Mediterraneo y Roma Capannelle.","El ministerio aplicó los criterios de un decreto de 6 de diciembre de 2024. El expediente en la web del ministerio incluye también el informe explicativo, las fichas de criterios y un informe de clasificación de la Universidad de Nápoles Parthenope."]},"ru":{"mkt":"Италия","auth":"Masaf","t":"Италия: министерство сельского хозяйства распределило по классам 20 ипподромов для рысистых и 14 для скаковых бегов на 2027 год","d":"Декрет Masaf от 31 октября обновляет классификацию итальянских ипподромов на 2027 год, первые места заняли Torino Stupinigi и Milano San Siro.","b":["Министерство сельского хозяйства Италии (Masaf) обновило классификацию ипподромов на 2027 год. Директорский декрет № 598837 от 31 октября 2026 года охватывает ипподромы, действовавшие на эту дату.","Классификация, приведенная в приложении A, включает 20 ипподромов для рысистых бегов и 14 для скачек. Список рысистых ипподромов возглавляет Torino Stupinigi, за ним следуют Bologna Arcoveggio и Napoli Agnano. Список скаковых возглавляет Milano San Siro, за ним Siracusa del Mediterraneo и Roma Capannelle.","Министерство применило критерии декрета от 6 декабря 2024 года. В деле на сайте министерства также есть пояснительная записка, листы критериев и отчет о классификации Неаполитанского университета Parthenope."]}},{"id":"fi-police-board-first-18-licences","reg":"Europe","mk":"FI","mkt":"Finland","auth":"National Police Board","cat":"Licensing","date":"2026-10-29","v":"official","t":"Finland: Police Board grants first 18 online gambling licences under the new law","d":"Finland's National Police Board granted the first licences under the new gambling law to 18 companies, with 63 applications still pending.","b":["Finland's National Police Board granted the first licences under the new gambling law to 18 companies, the public broadcaster Yle reported on 29 October 2026. Another 63 applications are still being processed. Most applicants are foreign companies.","Licence holders may offer and market betting and online casino games from 1 July 2027. Most licences are valid until 30 June 2032.","Licensing and supervision move from the Police Board to the Licensing and Supervision Agency in July 2027. Background: on 26 October the Police Board gave a count of 12 approved applications."],"src":[["Yle, first gambling licences granted, 29 Oct 2026","https://yle.fi/a/74-20254037","o"],["Police Board, licences under the Gambling Act","https://poliisi.fi/en/licences-under-the-gambling-act","o"]],"es":{"mkt":"Finlandia","auth":"Junta Nacional de Policía","t":"Finlandia: la Junta de Policía concede las primeras 18 licencias de juego online con la nueva ley","d":"La Junta Nacional de Policía de Finlandia concedió a 18 empresas las primeras licencias de la nueva ley del juego, y 63 solicitudes siguen pendientes.","b":["La Junta Nacional de Policía de Finlandia concedió a 18 empresas las primeras licencias de la nueva ley del juego, informó la radiotelevisión pública Yle el 29 de octubre de 2026. Otras 63 solicitudes siguen en trámite. La mayoría de los solicitantes son empresas extranjeras.","Los titulares de licencias podrán ofrecer y promocionar apuestas y juegos de casino online desde el 1 de julio de 2027. La mayoría de las licencias son válidas hasta el 30 de junio de 2032.","La concesión de licencias y la supervisión pasan de la Junta de Policía a la Agencia de Licencias y Supervisión en julio de 2027. Antecedentes: el 26 de octubre la Junta de Policía contaba 12 solicitudes aprobadas."]},"ru":{"mkt":"Финляндия","auth":"Национальное полицейское управление","t":"Финляндия: Полицейское управление выдало первые 18 лицензий на онлайн-гемблинг по новому закону","d":"Национальное полицейское управление Финляндии выдало первые лицензии по новому закону об азартных играх 18 компаниям, еще 63 заявки на рассмотрении.","b":["Национальное полицейское управление Финляндии выдало первые лицензии по новому закону об азартных играх 18 компаниям, сообщила 29 октября 2026 года общественная телерадиокомпания Yle. Еще 63 заявки находятся на рассмотрении. Большинство заявителей составляют иностранные компании.","Владельцы лицензий смогут предлагать и рекламировать ставки и онлайн-казино с 1 июля 2027 года. Большинство лицензий действуют до 30 июня 2032 года.","В июле 2027 года лицензирование и надзор перейдут от Полицейского управления к Агентству по лицензированию и надзору. Справочно: 26 октября Полицейское управление сообщало об одобрении 12 заявок."]}},{"id":"ro-negreni-hcl-109-ban","reg":"Europe","mk":"RO","mkt":"Romania","auth":"Negreni Local Council","cat":"Licensing","date":"2026-10-29","v":"official","t":"Romania: Negreni commune council bans gambling on its territory","d":"The local council of Negreni commune in Cluj county adopted decision no. 109 of 29 October banning gambling activities across its administrative territory.","b":["The local council of Negreni commune in Cluj county adopted decision no. 109 of 29 October 2026 banning gambling activities on the commune's administrative territory. The commune hall posted the decision on 11 November 2026.","The posted text does not show the legal basis or the date of entry into force."],"src":[["Negreni commune hall, HCL no. 109 of 29.10.2026","https://primarianegreni.ro/hcl-nr-109-29-10-2026-privind-interzicerea-desfasurarii-activitatilor-de-jocuri-de-noroc-pe-teritoriul-administrativ-al-comunei-negreni/","o"],["Negreni commune hall, decision PDF","https://primarianegreni.ro/wp-content/uploads/hcl-109-interzicere-jocuri-de-noroc.pdf","o"]],"es":{"mkt":"Rumanía","auth":"Consejo Local de Negreni","t":"Rumanía: el consejo del municipio de Negreni prohíbe el juego en su territorio","d":"El consejo local del municipio de Negreni, en el distrito de Cluj, aprobó la decisión n.º 109 de 29 de octubre, que prohíbe las actividades de juego en todo su territorio administrativo.","b":["El consejo local del municipio de Negreni, en el distrito de Cluj, aprobó la decisión n.º 109 de 29 de octubre de 2026, que prohíbe las actividades de juego en el territorio administrativo del municipio. El ayuntamiento publicó la decisión el 11 de noviembre de 2026.","El texto publicado no indica la base legal ni la fecha de entrada en vigor."]},"ru":{"mkt":"Румыния","auth":"Местный совет Негрени","t":"Румыния: совет коммуны Негрени запретил азартные игры на своей территории","d":"Местный совет коммуны Негрени в жудеце Клуж принял решение № 109 от 29 октября о запрете деятельности в сфере азартных игр на всей своей административной территории.","b":["Местный совет коммуны Негрени в жудеце Клуж принял решение № 109 от 29 октября 2026 года о запрете деятельности в сфере азартных игр на административной территории коммуны. Мэрия коммуны опубликовала решение 11 ноября 2026 года.","В опубликованном тексте не указаны правовое основание и дата вступления в силу."]}}]);
